window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a3fa2a79a5eb64e3"]={"versions": [{"id": "FIG-a3fa2a79a5eb64e3", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR BSW-Schichten- und Schnittstellendiagramm (Layered Architecture & Component Interaction Overview).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung der strukturellen Einbettung des BSW-Moduls <code>Firewall</code> in den Kommunikations-, Treiber- und Security-Stack der AUTOSAR Classic Platform (ab Release R21-11 / R23-11).</li>\n<li><strong>Funktionale Einordnung:</strong> Das Diagramm verortet die <code>Firewall</code> auf der Abstraktions- und Serviceebene. Es zeigt die operative Bindung an die Kommunikationsabstraktion (<code>EthIf</code>) zur Ingress-/Egress-Paketfilterung sowie die Anbindung an systemweite Steuerungs- (<code>BswM</code>) und Überwachungsinstanzen (<code>IdsM</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Module (Bottom-Up)</p>\n<ol class=\"fig-list\">\n<li><strong>Microcontroller-Ebene ($\\mu\\text{C}$):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Ethernet</code>: On-Chip Ethernet-MAC/Controller.</li>\n<li><code>MII</code> (Media Independent Interface): Physische/mediale Schnittstelle zur Anbindung externer Controller oder Switches.</li>\n<li><code>External Ethernet Controller</code>: Externer MAC/Switch-Baustein außerhalb des SoC.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>MCAL / Treiber-Schicht (Drivers):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>I/O Drivers:</strong></li>\n<li><code>DIO Driver</code>: Digitale I/O-Pins (GPIO) zur Hardware-Steuerung (z. B. Reset-, Power- und Interrupt-Leitungen von PHY/Switch).</li>\n<li><strong>Communication Drivers:</strong></li>\n<li><code>Ethernet Driver</code> (<code>Eth</code>): Hardwarenaher Treiber für den internen MAC-Controller.</li>\n<li><code>Handler / Driver</code>: Steuer- und Bustreiber (z. B. <code>Spi</code> oder Memory-Mapped I/O) zur Konfiguration externer Controller/Switches.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication Hardware Abstraction:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Ethernet Interface</code> (<code>EthIf</code>): Zentrale Abstraktionsschicht, die Controller-, Transceiver- und Switch-Treiber logisch bündelt und obere Schichten von Hardware-Spezifika entkoppelt.</li>\n<li><code>Ethernet Switch Driver</code> (<code>EthSwt</code>): Ansteuerung und Port-Management für Ethernet-Switches.</li>\n<li><code>Ethernet Transceiver Driver</code> (<code>EthTrcv</code>): PHY-Management (Link-Status, Auto-Negotiation, Power Modes).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Security & System Services:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Firewall</code>: Autonomes BSW-Modul zur zustandsbasierten oder statischen Filterung von Ethernet-Frames (L2 bis L4).</li>\n<li><code>BswM</code> (Basic Software Mode Manager): Zentraler Modus-Manager der Plattform.</li>\n<li><code>IdsM</code> (Intrusion Detection System Manager): BSW-Service zur Aggregation, Qualifizierung und Filterung sicherheitsrelevanter Anomalien.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>EthIf</code> $\\longleftrightarrow$ <code>Firewall</code> (Bidirektional):</strong></li>\n<li><code>EthIf</code> übergibt empfangene Frames oder auszusendende Frames zur Inspektion an die Firewall (Callout-/Filter-Interface).</li>\n<li>Die <code>Firewall</code> liefert einen synchronen Filterentscheid (<code>PASS</code> vs. <code>DROP</code>) an <code>EthIf</code> zurück.</li>\n<li><strong><code>BswM</code> $\\longrightarrow$ <code>Firewall</code> (<code>Firewall state</code>):</strong></li>\n<li>Unidirektionaler Steuerpfad zur Umschaltung des Firewall-Betriebszustands (z. B. Initialisierung, Bypass-Modus, selektive Regelsatzumschaltung je nach Fahrzeug-/ECU-Betriebszustand).</li>\n<li><strong><code>Firewall</code> $\\longrightarrow$ <code>IdsM</code> (<code>Security events</code>):</strong></li>\n<li>Unidirektionaler Meldepfad via standardisierter Security-Event-API (<code>IdsM_SetSecurityEvent</code>). Wird getriggert bei verworfenen Paketen, unautorisierten MAC/IP-Adressen oder erkannten Anomalien.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Ingress-Paketprüfung (Rx-Pfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Frame-Empfang:</strong> Ein Frame gelangt über den On-Chip MAC oder den externen Controller via <code>Eth</code> in den RX-Puffer.</li>\n<li><strong>Indikation:</strong> <code>Eth</code> meldet den Frame via <code>EthIf_RxIndication()</code> an das <code>EthIf</code>.</li>\n<li><strong>Firewall-Hook:</strong> Bevor der Frame an obere Protokollschichten (<code>TcpIp</code>, <code>SomeIpXf</code>, <code>SoAd</code>) oder andere Switch-Ports weitergeleitet wird, ruft <code>EthIf</code> die Prüfroutine der <code>Firewall</code> auf.</li>\n<li><strong>Verifikationsschleife:</strong> Die Firewall prüft Header-Felder (EtherType, VLAN-ID, MAC-Adressen, IPv4/IPv6-Header, TCP/UDP-Ports) gegen die aktuell aktiven Filterregeln.</li>\n<li><strong>Entscheidungszweige:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Verdict = PASS:</strong> <code>EthIf</code> setzt die reguläre Demultiplexierung und Weiterleitung im Stack fort.</li>\n<li><strong>Verdict = DROP:</strong> <code>EthIf</code> verwirft den Frame unverzüglich und gibt den Rx-Puffer frei.</li>\n<li><strong>Security Event Trigger:</strong> Die <code>Firewall</code> meldet die Regelverletzung synchron oder entkoppelt an den <code>IdsM</code> (<code>IdsM_SetSecurityEvent(EventId, ContextData)</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Moduswechsel via Mode Management</p>\n<ol class=\"fig-list\">\n<li><code>BswM</code> detektiert einen Zustandswechsel (z. B. Übergang von <em>Normal Operation</em> zu <em>Diagnostic / Flashing</em>).</li>\n<li><code>BswM</code> führt eine konfigurierte Aktion aus und setzt den Betriebsmodus der <code>Firewall</code> über eine Modus-Anforderungs-API.</li>\n<li>Die <code>Firewall</code> aktiviert den entsprechenden Regelsatz atomar, um ohne Frame-Verlust im laufenden Betrieb zwischen permissiven und restriktiven Policies zu wechseln.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Stack-Konfiguration (<code>EthIf</code> & <code>Firewall</code>):</strong></li>\n<li>Im <code>EthIf</code> muss der Firewall-Support explizit per Konfigurationsparameter (<code>EthIfFirewallSupport = TRUE</code>) einkompiliert werden. Fehlt dieser, werden Frames ungeprüft geroutet/nach oben gereicht.</li>\n<li>Filterregeln (<code>FirewallRule</code>, <code>FirewallFilterRuleSet</code>) müssen vollständig in ARXML spezifiziert werden. Die Zuweisung zu Interfaces und Switch-Ports erfordert deterministische Referenzen auf <code>EthIfController</code> bzw. <code>EthIfSwitchPortGroup</code>.</li>\n<li><strong>Ausführungs- und Latenzanforderungen (Echtzeit-Budget):</strong></li>\n<li>Die Firewall-Prüfung liegt im synchronen Rx-Pfad des <code>EthIf</code>. Filteralgorithmen müssen $O(1)$- oder streng deterministisches $O(n)$-Laufzeitverhalten aufweisen.</li>\n<li>Keine dynamische Speicherallokation, keine blockierenden Operationen und keine langwierigen kryptografischen Prüfungen innerhalb des Filter-Hooks, um Rx-Pufferüberläufe und Frame-Drops legitimer Pakete zu vermeiden.</li>\n<li><strong>Security-Event-Rate-Limiting (IdsM-Interaktion):</strong></li>\n<li>Bei DoS-Angriffen (Flooding ungültiger Pakete) darf die Firewall den <code>IdsM</code> nicht überlasten. Entwickler müssen im <code>IdsM</code> geeignete Filter- und Aggregationsstrategien (Thresholding, Context Sampling) konfigurieren.</li>\n<li><strong>Hardware-Offloading:</strong></li>\n<li>Ist ein intelligenter Hardware-Switch vorhanden (<code>EthSwt</code>), können Teile der L2/VLAN-Filterung direkt in die Switch-Hardware (Access Control Lists / TCAM) delegiert werden, während komplexe L3/L4-Inspektionen in der BSW-<code>Firewall</code> verbleiben.</li>\n</ul>"}, {"id": "FIG-d28837567f45e802", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR BSW-Schichten- und Schnittstellendiagramm (Layered Architecture & Component Interaction Overview).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung der strukturellen Einbettung des BSW-Moduls <code>Firewall</code> in den Kommunikations-, Treiber- und Security-Stack der AUTOSAR Classic Platform (ab Release R24-11).</li>\n<li><strong>Funktionale Einordnung:</strong> Das Diagramm verortet die <code>Firewall</code> auf der Abstraktions- und Serviceebene. Es zeigt die operative Bindung an die Kommunikationsabstraktion über den <code>L-SDU Router</code> zur Ingress-/Egress-Paketfilterung sowie die Anbindung an systemweite Steuerungs- (<code>BswM</code>) und Überwachungsinstanzen (<code>IdsM</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Module (Bottom-Up)</p>\n<ol class=\"fig-list\">\n<li><strong>Microcontroller-Ebene ($\\mu\\text{C}$):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Ethernet</code>: On-Chip Ethernet-MAC/Controller.</li>\n<li><code>MII</code> (Media Independent Interface): Physische/mediale Schnittstelle zur Anbindung externer Controller oder Switches.</li>\n<li><code>External Ethernet Controller</code>: Externer MAC/Switch-Baustein außerhalb des SoC.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>MCAL / Treiber-Schicht (Drivers):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>I/O Drivers:</strong></li>\n<li><code>DIO Driver</code>: Digitale I/O-Pins (GPIO) zur Hardware-Steuerung (z. B. Reset-, Power- und Interrupt-Leitungen von PHY/Switch).</li>\n<li><strong>Communication Drivers:</strong></li>\n<li><code>Ethernet Driver</code> (<code>Eth</code>): Hardwarenaher Treiber für den internen MAC-Controller.</li>\n<li><code>Handler / Driver</code>: Steuer- und Bustreiber (z. B. <code>Spi</code> oder Memory-Mapped I/O) zur Konfiguration externer Controller/Switches.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication Hardware Abstraction:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>L-SDU Router</code>: Routing- und Filterungs-Kopplungsinstanz für Ethernet L-SDUs oberhalb des Interface-Treibers.</li>\n<li><code>Ethernet Interface</code> (<code>EthIf</code>): Zentrale Abstraktionsschicht, die Controller-, Transceiver- und Switch-Treiber logisch bündelt und obere Schichten von Hardware-Spezifika entkoppelt.</li>\n<li><code>Ethernet Switch Driver</code> (<code>EthSwt</code>): Ansteuerung und Port-Management für Ethernet-Switches.</li>\n<li><code>Ethernet Transceiver Driver</code> (<code>EthTrcv</code>): PHY-Management (Link-Status, Auto-Negotiation, Power Modes).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Security & System Services:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Firewall</code>: Autonomes BSW-Modul zur zustandsbasierten oder statischen Filterung von Ethernet-Frames/L-SDUs (L2 bis L4).</li>\n<li><code>BswM</code> (Basic Software Mode Manager): Zentraler Modus-Manager der Plattform.</li>\n<li><code>IdsM</code> (Intrusion Detection System Manager): BSW-Service zur Aggregation, Qualifizierung und Filterung sicherheitsrelevanter Anomalien.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>L-SDU Router</code> $\\longleftrightarrow$ <code>Firewall</code> (Bidirektional):</strong></li>\n<li><code>L-SDU Router</code> übergibt L-SDUs zur Inspektion an die Firewall (Callout-/Filter-Interface).</li>\n<li>Die <code>Firewall</code> liefert einen synchronen Filterentscheid (<code>PASS</code> vs. <code>DROP</code>) an den <code>L-SDU Router</code> zurück.</li>\n<li><strong><code>BswM</code> $\\longrightarrow$ <code>Firewall</code> (<code>Firewall state</code>):</strong></li>\n<li>Unidirektionaler Steuerpfad zur Umschaltung des Firewall-Betriebszustands (z. B. Initialisierung, Bypass-Modus, selektive Regelsatzumschaltung je nach Fahrzeug-/ECU-Betriebszustand).</li>\n<li><strong><code>Firewall</code> $\\longrightarrow$ <code>IdsM</code> (<code>Security events</code>):</strong></li>\n<li>Unidirektionaler Meldepfad via standardisierter Security-Event-API (<code>IdsM_SetSecurityEvent</code>). Wird getriggert bei verworfenen Paketen, unautorisierten MAC/IP-Adressen oder erkannten Anomalien.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Ingress-Paketprüfung (Rx-Pfad)</p>\n<ol class=\"fig-list\">\n<li><strong>Frame-Empfang:</strong> Ein Frame gelangt über den On-Chip MAC oder den externen Controller via <code>Eth</code> in den RX-Puffer.</li>\n<li><strong>Indikation:</strong> <code>Eth</code> meldet den Frame via <code>EthIf_RxIndication()</code> an das <code>EthIf</code>, welches die L-SDU an den <code>L-SDU Router</code> weiterreicht.</li>\n<li><strong>Firewall-Hook:</strong> Der <code>L-SDU Router</code> übernimmt die L-SDU und ruft vor dem weiteren Routing bzw. der Weiterleitung an obere Protokollschichten oder Switch-Ports die Prüfroutine der <code>Firewall</code> auf.</li>\n<li><strong>Verifikationsschleife:</strong> Die Firewall prüft Header-Felder (EtherType, VLAN-ID, MAC-Adressen, IPv4/IPv6-Header, TCP/UDP-Ports) gegen die aktuell aktiven Filterregeln.</li>\n<li><strong>Entscheidungszweige:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Verdict = PASS:</strong> Der <code>L-SDU Router</code> setzt das reguläre Routing und die Weiterleitung im Stack fort.</li>\n<li><strong>Verdict = DROP:</strong> Die L-SDU wird verworfen und der Puffer freigegeben.</li>\n<li><strong>Security Event Trigger:</strong> Die <code>Firewall</code> meldet die Regelverletzung synchron oder entkoppelt an den <code>IdsM</code> (<code>IdsM_SetSecurityEvent(EventId, ContextData)</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Moduswechsel via Mode Management</p>\n<ol class=\"fig-list\">\n<li><code>BswM</code> detektiert einen Zustandswechsel (z. B. Übergang von <em>Normal Operation</em> zu <em>Diagnostic / Flashing</em>).</li>\n<li><code>BswM</code> führt eine konfigurierte Aktion aus und setzt den Betriebsmodus der <code>Firewall</code> über eine Modus-Anforderungs-API.</li>\n<li>Die <code>Firewall</code> aktiviert den entsprechenden Regelsatz atomar, um ohne Frame-Verlust im laufenden Betrieb zwischen permissiven und restriktiven Policies zu wechseln.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Stack-Konfiguration (<code>L-SDU Router</code> / <code>EthIf</code> & <code>Firewall</code>):</strong></li>\n<li>Im Kommunikations-Stack muss der Firewall-Support für das L-SDU-Routing explizit konfiguriert werden. Fehlt dieser, werden L-SDUs ungeprüft weitergeleitet bzw. geroutet.</li>\n<li>Filterregeln (<code>FirewallRule</code>, <code>FirewallFilterRuleSet</code>) müssen vollständig in ARXML spezifiziert werden. Die Zuweisung erfordert deterministische Referenzen auf die Routing-Pfade, Schnittstellen und Switch-Ports.</li>\n<li><strong>Ausführungs- und Latenzanforderungen (Echtzeit-Budget):</strong></li>\n<li>Die Firewall-Prüfung liegt im synchronen Pfad des <code>L-SDU Router</code>. Filteralgorithmen müssen $O(1)$- oder streng deterministisches $O(n)$-Laufzeitverhalten aufweisen.</li>\n<li>Keine dynamische Speicherallokation, keine blockierenden Operationen und keine langwierigen kryptografischen Prüfungen innerhalb des Filter-Hooks, um Pufferüberläufe und Frame-Drops legitimer Pakete zu vermeiden.</li>\n<li><strong>Security-Event-Rate-Limiting (IdsM-Interaktion):</strong></li>\n<li>Bei DoS-Angriffen (Flooding ungültiger Pakete) darf die Firewall den <code>IdsM</code> nicht überlasten. Entwickler müssen im <code>IdsM</code> geeignete Filter- und Aggregationsstrategien (Thresholding, Context Sampling) konfigurieren.</li>\n<li><strong>Hardware-Offloading:</strong></li>\n<li>Ist ein intelligenter Hardware-Switch vorhanden (<code>EthSwt</code>), können Teile der L2/VLAN-Filterung direkt in die Switch-Hardware (Access Control Lists / TCAM) delegiert werden, während komplexe L3/L4-Inspektionen in der BSW-<code>Firewall</code> verbleiben.</li>\n</ul>"}], "trans": [{"from": "FIG-a3fa2a79a5eb64e3", "to": "FIG-d28837567f45e802", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>Communication Hardware Abstraction</code>: Neue Komponente <code>L-SDU Router</code> oberhalb von <code>Ethernet Interface</code> hinzugefügt.</li>\n<li>Schnittstelle <code>Firewall</code>: Der bidirektionale Interaktionspfad zur <code>Firewall</code> bindet nicht mehr direkt an das <code>Ethernet Interface</code> an, sondern verbindet nun <code>L-SDU Router</code> und <code>Firewall</code>.</li>\n<li>Diagramm-Layout: <code>BswM</code> und <code>IdsM</code> vertikal nach oben versetzt, Verbindungspfeile <code>Firewall state</code> und <code>Security events</code> entsprechend nach oben verlängert.</li>\n</ul>"}]};
